/**
 * Firm-wide statutory calendar.
 *
 * The due dates are generated by `lib/engine/compliance-calendar.ts`; this
 * module only supplies each client's registration facts and merges the firm's
 * filed/waived state. Nothing about the dates is stored, so a rule change takes
 * effect on the next read without backfilling rows.
 *
 * A client without a saved profile still appears, using conservative defaults
 * derived from the engagement (GST if a GSTIN is on file, TDS deductor assumed).
 *
 * tenancy-audit: global-operator — compliance calendar supplies registration
 * facts and filed/waived state. This is a deployment-wide aggregate rather than
 * a per-tenant query.
 * It is labelled `configured: false` so the UI asks the firm to confirm rather
 * than silently treating defaults as fact.
 */

import { ApiError, type AuthContext } from "@/lib/auth/guard";
import { prisma } from "@/lib/db";
import {
  buildClientComplianceCalendar,
  complianceTaskState,
  financialYearFor,
  parseFinancialYear,
  type ClientComplianceProfileInput,
  type ComplianceTask,
  type ComplianceTaskState,
  type EntityKind,
  type GstFrequency,
} from "@/lib/engine/compliance-calendar";
import { requireEngagementRole } from "@/lib/server/engagement";
import { requireOrgRole } from "@/lib/server/members";
import { withTenantDb } from "@/lib/server/tenant-db";

export interface ComplianceProfileSeed {
  entityKind: EntityKind;
  financialYear: string;
  gstRegistered: boolean;
  gstFrequency: GstFrequency;
  tdsDeductor: boolean;
  taxAuditApplicable: boolean;
  transferPricingApplicable: boolean;
  listedCompany: boolean;
  state: string | null;
  employsStaff: boolean;
}

export interface ComplianceTaskView extends ComplianceTask {
  engagementCode: string | null;
  state: ComplianceTaskState;
  filedOn: string | null;
  reference: string | null;
}

export interface ComplianceClientView {
  id: string;
  name: string;
  code: string | null;
  configured: boolean;
  profile: ComplianceProfileSeed;
}

export interface ComplianceCalendarResult {
  asOf: string;
  financialYear: string;
  clients: ComplianceClientView[];
  tasks: ComplianceTaskView[];
  totals: {
    clients: number;
    unconfigured: number;
    overdue: number;
    dueSoon: number;
    upcoming: number;
    filed: number;
    waived: number;
  };
}

const MAX_CLIENTS = 100;

export function defaultProfile(financialYear: string, gstin: string | null): ComplianceProfileSeed {
  return {
    entityKind: "company",
    financialYear,
    gstRegistered: Boolean(gstin),
    gstFrequency: "monthly",
    tdsDeductor: true,
    taxAuditApplicable: false,
    transferPricingApplicable: false,
    listedCompany: false,
    state: null,
    employsStaff: false,
  };
}

/** Read the firm calendar for `today` (ISO date, injectable for tests/tools). */
export async function getComplianceCalendar(
  ctx: AuthContext,
  opts: { today?: string } = {},
): Promise<ComplianceCalendarResult> {
  if (!ctx.organization) throw new ApiError(404, "NO_ORGANIZATION", "Create an organization first.");
  const organizationId = ctx.organization.id;
  await requireOrgRole(ctx, organizationId, "MEMBER");

  const today = opts.today ?? new Date().toISOString().slice(0, 10);
  const [engagements, profiles, statuses] = await Promise.all([
    withTenantDb(ctx, (db) =>
      db.engagement.findMany({
        where: { organizationId, status: { not: "ARCHIVED" } },
        select: { id: true, name: true, code: true, gstin: true },
        orderBy: { name: "asc" },
        take: MAX_CLIENTS,
      }),
    ),
    withTenantDb(ctx, (db) =>
      db.clientComplianceProfile.findMany({
        where: { organizationId },
        select: { engagementId: true, profile: true },
      }),
    ),
    withTenantDb(ctx, (db) =>
      db.clientComplianceStatus.findMany({
        where: { organizationId },
        select: { engagementId: true, taskId: true, status: true, filedOn: true, reference: true },
      }),
    ),
  ]);

  const profileByEngagement = new Map(profiles.map((p) => [p.engagementId, p.profile]));
  const statusByTask = new Map(statuses.map((s) => [`${s.engagementId}:${s.taskId}`, s]));

  const clients: ComplianceClientView[] = [];
  const tasks: ComplianceTaskView[] = [];
  const totals = { clients: 0, unconfigured: 0, overdue: 0, dueSoon: 0, upcoming: 0, filed: 0, waived: 0 };

  for (const engagement of engagements) {
    const stored = readProfile(profileByEngagement.get(engagement.id));
    const profile = stored ?? defaultProfile(financialYearFor(today), engagement.gstin);
    const input: ClientComplianceProfileInput = {
      ...profile,
      clientId: engagement.id,
      clientName: engagement.name,
    };

    let generated: ComplianceTask[];
    try {
      generated = buildClientComplianceCalendar(input);
    } catch {
      // A malformed stored FY must not take the whole firm calendar down.
      generated = buildClientComplianceCalendar({
        ...defaultProfile(financialYearFor(today), engagement.gstin),
        clientId: engagement.id,
        clientName: engagement.name,
      });
    }

    clients.push({
      id: engagement.id,
      name: engagement.name,
      code: engagement.code,
      configured: stored !== null,
      profile,
    });
    totals.clients += 1;
    if (!stored) totals.unconfigured += 1;

    for (const task of generated) {
      const filed = statusByTask.get(`${engagement.id}:${task.id}`);
      const filedStatus: "filed" | "waived" | null =
        filed?.status === "filed" ? "filed" : filed?.status === "waived" ? "waived" : null;
      const state = complianceTaskState(task.dueDate, today, filedStatus);
      if (state === "overdue") totals.overdue += 1;
      else if (state === "due-soon") totals.dueSoon += 1;
      else if (state === "upcoming") totals.upcoming += 1;
      else if (state === "filed") totals.filed += 1;
      else totals.waived += 1;

      tasks.push({
        ...task,
        engagementCode: engagement.code,
        state,
        filedOn: filed?.filedOn ?? null,
        reference: filed?.reference ?? null,
      });
    }
  }

  tasks.sort((a, b) => a.dueDate.localeCompare(b.dueDate) || a.clientName.localeCompare(b.clientName));

  return {
    asOf: today,
    financialYear: financialYearFor(today),
    clients,
    tasks,
    totals,
  };
}

function readProfile(raw: string | undefined): ComplianceProfileSeed | null {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as Partial<ComplianceProfileSeed>;
    if (!parsed || typeof parsed !== "object" || typeof parsed.financialYear !== "string") return null;
    parseFinancialYear(parsed.financialYear);
    return {
      entityKind: parsed.entityKind ?? "company",
      financialYear: parsed.financialYear,
      gstRegistered: Boolean(parsed.gstRegistered),
      gstFrequency: parsed.gstFrequency === "quarterly" ? "quarterly" : "monthly",
      tdsDeductor: Boolean(parsed.tdsDeductor),
      taxAuditApplicable: Boolean(parsed.taxAuditApplicable),
      transferPricingApplicable: Boolean(parsed.transferPricingApplicable),
      listedCompany: Boolean(parsed.listedCompany),
      state: parsed.state ?? null,
      employsStaff: Boolean(parsed.employsStaff),
    };
  } catch {
    return null;
  }
}

/** Save the registration profile that drives this client's calendar. */
export async function upsertComplianceProfile(
  ctx: AuthContext,
  engagementId: string,
  input: ComplianceProfileSeed,
): Promise<{ profile: ComplianceProfileSeed }> {
  const { engagement } = await requireEngagementRole(ctx, engagementId, "MANAGER");
  parseFinancialYear(input.financialYear);

  const row = await prisma.clientComplianceProfile.upsert({
    where: { engagementId: engagement.id },
    create: {
      organizationId: engagement.organizationId,
      engagementId: engagement.id,
      profile: JSON.stringify(input),
      createdById: ctx.user.id,
      updatedById: ctx.user.id,
    },
    update: {
      profile: JSON.stringify(input),
      updatedById: ctx.user.id,
    },
  });
  return { profile: readProfile(row.profile) ?? input };
}

export interface ComplianceStatusInput {
  taskId: string;
  status: "filed" | "waived" | "pending";
  filedOn?: string | null;
  reference?: string | null;
}

/** Record (or clear) the firm's filing state for one generated obligation. */
export async function setComplianceTaskStatus(
  ctx: AuthContext,
  engagementId: string,
  input: ComplianceStatusInput,
): Promise<{ taskId: string; status: string }> {
  const { engagement } = await requireEngagementRole(ctx, engagementId, "ASSISTANT");

  const stored = await prisma.clientComplianceProfile.findUnique({
    where: { engagementId: engagement.id },
    select: { profile: true },
  });
  const profile = readProfile(stored?.profile ?? undefined) ?? defaultProfile(
    financialYearFor(new Date().toISOString().slice(0, 10)),
    null,
  );
  const generated = buildClientComplianceCalendar({
    ...profile,
    clientId: engagement.id,
    clientName: engagement.name ?? "Client",
  });
  if (!generated.some((task) => task.id === input.taskId)) {
    throw new ApiError(400, "VALIDATION", "That task does not belong to this client's current calendar.");
  }

  if (input.status === "pending") {
    await prisma.clientComplianceStatus.deleteMany({
      where: { engagementId: engagement.id, taskId: input.taskId },
    });
    return { taskId: input.taskId, status: "pending" };
  }

  await prisma.clientComplianceStatus.upsert({
    where: { engagementId_taskId: { engagementId: engagement.id, taskId: input.taskId } },
    create: {
      organizationId: engagement.organizationId,
      engagementId: engagement.id,
      taskId: input.taskId,
      status: input.status,
      filedOn: input.filedOn ?? new Date().toISOString().slice(0, 10),
      reference: input.reference ?? null,
      updatedById: ctx.user.id,
    },
    update: {
      status: input.status,
      filedOn: input.filedOn ?? new Date().toISOString().slice(0, 10),
      reference: input.reference ?? null,
      updatedById: ctx.user.id,
    },
  });
  return { taskId: input.taskId, status: input.status };
}
